create table if not exists public.sellora_public_content (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null default '',
  seo_title text not null default '',
  seo_description text not null default '',
  draft_content jsonb not null default '{}'::jsonb,
  published_content jsonb not null default '{}'::jsonb,
  draft_version integer not null default 1,
  published_version integer not null default 0,
  published boolean not null default false,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null,
  published_at timestamptz,
  published_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create table if not exists public.sellora_contact_submissions (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text not null,
  phone text,
  company text,
  restaurant_count integer,
  subject text,
  message text not null,
  status text not null default 'NEW' check (status in ('NEW','IN_PROGRESS','CONTACTED','CONVERTED','CLOSED')),
  internal_notes text,
  source text not null default 'website',
  ip_hash text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null
);

create index if not exists sellora_public_content_published_idx on public.sellora_public_content(slug, published);
create index if not exists sellora_contact_submissions_created_idx on public.sellora_contact_submissions(created_at desc);
create index if not exists sellora_contact_submissions_status_idx on public.sellora_contact_submissions(status, created_at desc);

alter table public.sellora_public_content enable row level security;
alter table public.sellora_contact_submissions enable row level security;

 drop policy if exists sellora_public_content_public_read on public.sellora_public_content;
 create policy sellora_public_content_public_read on public.sellora_public_content
   for select to anon, authenticated using (published = true);

 drop policy if exists sellora_public_content_service_only on public.sellora_public_content;
 create policy sellora_public_content_service_only on public.sellora_public_content
   for all to anon, authenticated using (false) with check (false);

 drop policy if exists sellora_contact_service_only on public.sellora_contact_submissions;
 create policy sellora_contact_service_only on public.sellora_contact_submissions
   for all to anon, authenticated using (false) with check (false);

insert into public.sellora_public_content (slug,title,seo_title,seo_description,draft_content,published_content,published,published_version)
values
('home','Sellora','Sellora — Creator commerce, simplified.','Create a storefront, sell digital products, accept payments and deliver securely.',
'{"heroEyebrow":"Built for independent creators","heroTitle":"Your audience. Your products. Your storefront.","heroDescription":"Create a storefront for your digital products, share one link everywhere, and turn your audience into customers without building your own commerce stack.","primaryCta":"Create your store →","primaryHref":"/signup","secondaryCta":"See an example","secondaryHref":"/krish","trustText":"Built for creators who sell from Instagram, WhatsApp and beyond.","featuresTitle":"A creator storefront, not another software project.","featuresDescription":"The product should disappear behind the thing creators care about: publishing great products and getting paid for them.","features":[{"title":"One link. Everything you sell.","description":"Turn your social bio into a beautiful storefront for courses, templates, guides, presets and assets."},{"title":"Get paid through your own account.","description":"Connect your payment account, let customers pay you directly, and keep your product revenue in your own payment relationship."},{"title":"Delivery without the support headache.","description":"Protect digital files with private storage and secure links after successful payment."}],"howTitle":"From audience to delivered product.","howDescription":"A deliberately short path from publishing to transaction.","howSteps":[{"title":"Create your storefront","description":"Claim your username, add your profile and make your public page yours."},{"title":"Connect payments","description":"Connect your own payment account and complete the provider setup required for selling."},{"title":"Get paid & deliver","description":"Customers pay through your connected payment account while Sellora handles the storefront, orders and secure delivery."}],"faq":[{"question":"What can I sell with Sellora?","answer":"Sell digital products such as courses, guides, templates, presets and other downloadable or link-based products."},{"question":"Do I receive my product-sale money?","answer":"Creator product sales use the creator''s connected payment relationship. Sellora subscriptions are separate."},{"question":"Does Sellora charge a transaction commission?","answer":"Sellora''s subscription model is separate from creator product-sale processing fees charged by the payment provider."}],"finalCtaTitle":"Ready to build your storefront?","finalCtaDescription":"Create your Sellora store and start publishing your products.","finalCtaText":"Get started","finalCtaHref":"/signup"}',
'{"heroEyebrow":"Built for independent creators","heroTitle":"Your audience. Your products. Your storefront.","heroDescription":"Create a storefront for your digital products, share one link everywhere, and turn your audience into customers without building your own commerce stack.","primaryCta":"Create your store →","primaryHref":"/signup","secondaryCta":"See an example","secondaryHref":"/krish","trustText":"Built for creators who sell from Instagram, WhatsApp and beyond.","featuresTitle":"A creator storefront, not another software project.","featuresDescription":"The product should disappear behind the thing creators care about: publishing great products and getting paid for them.","features":[{"title":"One link. Everything you sell.","description":"Turn your social bio into a beautiful storefront for courses, templates, guides, presets and assets."},{"title":"Get paid through your own account.","description":"Connect your payment account, let customers pay you directly, and keep your product revenue in your own payment relationship."},{"title":"Delivery without the support headache.","description":"Protect digital files with private storage and secure links after successful payment."}],"howTitle":"From audience to delivered product.","howDescription":"A deliberately short path from publishing to transaction.","howSteps":[{"title":"Create your storefront","description":"Claim your username, add your profile and make your public page yours."},{"title":"Connect payments","description":"Connect your own payment account and complete the provider setup required for selling."},{"title":"Get paid & deliver","description":"Customers pay through your connected payment account while Sellora handles the storefront, orders and secure delivery."}],"faq":[{"question":"What can I sell with Sellora?","answer":"Sell digital products such as courses, guides, templates, presets and other downloadable or link-based products."},{"question":"Do I receive my product-sale money?","answer":"Creator product sales use the creator''s connected payment relationship. Sellora subscriptions are separate."},{"question":"Does Sellora charge a transaction commission?","answer":"Sellora''s subscription model is separate from creator product-sale processing fees charged by the payment provider."}],"finalCtaTitle":"Ready to build your storefront?","finalCtaDescription":"Create your Sellora store and start publishing your products.","finalCtaText":"Get started","finalCtaHref":"/signup"}',true,1),
('contact','Contact Sellora','Sellora Contact','Contact the Sellora team.',
'{"eyebrow":"SELLORA","title":"Let’s build the right setup.","description":"Tell us about your creator business and our team will get in touch within 24 hours.","email":"krishsarkar456@gmail.com","location":"India, Kolkata","responseTime":"Within 24 hours","formTitle":"Start a conversation","formDescription":"Tell us what you are building and what you need.","successMessage":"Thanks. Your message has been received by the Sellora team."}',
'{"eyebrow":"SELLORA","title":"Let’s build the right setup.","description":"Tell us about your creator business and our team will get in touch within 24 hours.","email":"krishsarkar456@gmail.com","location":"India, Kolkata","responseTime":"Within 24 hours","formTitle":"Start a conversation","formDescription":"Tell us what you are building and what you need.","successMessage":"Thanks. Your message has been received by the Sellora team."}',true,1),
('vision','Our Vision','Sellora — Our Vision','Why Sellora exists and where creator commerce is going.',
'{"eyebrow":"OUR VISION","title":"Commerce should feel like part of your creative work.","intro":"Sellora exists to make selling digital products feel simple, direct and owned by the creator.","story":"Creators should be able to turn an audience into a sustainable business without assembling a complicated commerce stack. The storefront, payments, delivery and customer experience should work together while the creator stays focused on the product.","principles":[{"title":"Ownership","description":"Creators keep control of their storefront, products and customer experience."},{"title":"Simplicity","description":"Selling should not require becoming an expert in commerce infrastructure."},{"title":"Direct relationships","description":"Creators should build lasting relationships with the people who choose to buy from them."}],"closing":"We are building Sellora around a simple idea: the technology should get out of the way so creators can build the business behind their work.","ctaText":"Build your storefront","ctaHref":"/signup"}',
'{"eyebrow":"OUR VISION","title":"Commerce should feel like part of your creative work.","intro":"Sellora exists to make selling digital products feel simple, direct and owned by the creator.","story":"Creators should be able to turn an audience into a sustainable business without assembling a complicated commerce stack. The storefront, payments, delivery and customer experience should work together while the creator stays focused on the product.","principles":[{"title":"Ownership","description":"Creators keep control of their storefront, products and customer experience."},{"title":"Simplicity","description":"Selling should not require becoming an expert in commerce infrastructure."},{"title":"Direct relationships","description":"Creators should build lasting relationships with the people who choose to buy from them."}],"closing":"We are building Sellora around a simple idea: the technology should get out of the way so creators can build the business behind their work.","ctaText":"Build your storefront","ctaHref":"/signup"}',true,1),
('privacy','Privacy Policy','Sellora Privacy Policy','Sellora privacy policy.',
'{"lastUpdated":"19 September 2026","sections":[{"heading":"Information we collect","body":"Sellora may process account information, creator store information, customer order information, payment references, product-delivery records and technical information needed to operate the service."},{"heading":"How we use information","body":"We use information to provide accounts, storefronts, payments, orders, digital delivery, support, security, fraud prevention and service communications."},{"heading":"Payments","body":"Payment details are processed through the applicable payment provider. Sellora stores the provider references and transaction information needed to reconcile the transaction and provide the service."},{"heading":"Data sharing","body":"We share information with service providers only as needed to operate the service, process payments, deliver files, send communications, provide hosting and maintain security."},{"heading":"Your choices","body":"You may contact Sellora regarding account or personal information questions using the contact details on this website."}],"contact":"krishsarkar456@gmail.com"}',
'{"lastUpdated":"19 September 2026","sections":[{"heading":"Information we collect","body":"Sellora may process account information, creator store information, customer order information, payment references, product-delivery records and technical information needed to operate the service."},{"heading":"How we use information","body":"We use information to provide accounts, storefronts, payments, orders, digital delivery, support, security, fraud prevention and service communications."},{"heading":"Payments","body":"Payment details are processed through the applicable payment provider. Sellora stores the provider references and transaction information needed to reconcile the transaction and provide the service."},{"heading":"Data sharing","body":"We share information with service providers only as needed to operate the service, process payments, deliver files, send communications, provide hosting and maintain security."},{"heading":"Your choices","body":"You may contact Sellora regarding account or personal information questions using the contact details on this website."}],"contact":"krishsarkar456@gmail.com"}',true,1),
('terms','Terms & Conditions','Sellora Terms & Conditions','Terms governing use of Sellora.',
'{"lastUpdated":"19 September 2026","sections":[{"heading":"Using Sellora","body":"You are responsible for the information, products and content you publish through your Sellora account and for complying with applicable law."},{"heading":"Creator products","body":"Creators are responsible for their product descriptions, pricing, delivery configuration, customer support and any promises made to customers."},{"heading":"Payments and subscriptions","body":"Creator product sales use the creator''s configured payment relationship. Sellora subscription plans are separate and are billed according to the selected plan and applicable provider terms."},{"heading":"Acceptable use","body":"Do not use Sellora for unlawful, fraudulent, abusive or prohibited activity. Sellora may restrict access when necessary to protect the service, users or payment relationships."},{"heading":"Changes","body":"These terms may be updated from time to time. The public page records the date of the latest published version."}],"contact":"krishsarkar456@gmail.com"}',
