('refunds','Refund & Cancellation Policy','Sellora Refund & Cancellation Policy','Refund and cancellation policy for Sellora.',
'{"lastUpdated":"19 September 2026","sections":[{"heading":"Creator product purchases","body":"Refunds for creator products are governed by the creator''s published refund policy and the applicable payment-provider and consumer-protection rules. Sellora does not replace the creator''s responsibility for the promises made for a product."},{"heading":"Sellora subscriptions","body":"Subscription cancellation and any applicable refund are handled according to the selected Sellora plan terms and the subscription status shown in the creator billing area. Cancelling a subscription does not automatically mean that previously paid subscription periods are refundable."},{"heading":"Requesting help","body":"If you need help with a Sellora subscription or a transaction processed through the platform, contact Sellora with the relevant order or subscription reference so the issue can be reviewed."}],"contact":"krishsarkar456@gmail.com"}',
'{"lastUpdated":"19 September 2026","sections":[{"heading":"Creator product purchases","body":"Refunds for creator products are governed by the creator''s published refund policy and the applicable payment-provider and consumer-protection rules. Sellora does not replace the creator''s responsibility for the promises made for a product."},{"heading":"Sellora subscriptions","body":"Subscription cancellation and any applicable refund are handled according to the selected Sellora plan terms and the subscription status shown in the creator billing area. Cancelling a subscription does not automatically mean that previously paid subscription periods are refundable."},{"heading":"Requesting help","body":"If you need help with a Sellora subscription or a transaction processed through the platform, contact Sellora with the relevant order or subscription reference so the issue can be reviewed."}],"contact":"krishsarkar456@gmail.com"}',true,1)
on conflict (slug) do nothing;

create or replace function public.sellora_touch_contact_updated_at()
returns trigger language plpgsql security definer set search_path = public as $$
begin new.updated_at = now(); return new; end; $$;

drop trigger if exists sellora_contact_updated_at on public.sellora_contact_submissions;
create trigger sellora_contact_updated_at before update on public.sellora_contact_submissions for each row execute function public.sellora_touch_contact_updated_at();
